//
// The old /cfb guide (src/pages/Home.tsx), rewritten against the CURRENT
// board: the screenshots are fresh captures of the V2 scoreboard, Game sims
// and the Record (public/about/*.png, regenerated by
// scripts/capture_about_shots.py when the UI changes).

import { Link } from "react-router-dom";
import { ButtonLink, PageHeader } from "../../components/ui";
import { useDocumentMeta } from "../../lib/useDocumentMeta";

function Shot({ src, alt, caption, w, h }: { src: string; alt: string; caption: string; w: number; h: number }) {
  return (
    <figure className="hiw-shot">
      <img src={src} alt={alt} width={w} height={h} loading="lazy" decoding="async" />
      <figcaption>{caption}</figcaption>
    </figure>
  );
}

export default function HowItWorks() {
  useDocumentMeta({
    title: "How to read the board",
    description: "A plain-English guide to the MVPEAV college football board, the game sims and the record.",
  });
  return (
    <div className="stack hiw">
      <PageHeader kicker="About" title="How to read the board"
        sub="Three pages do most of the work: the board for this week, Game sims for one game in depth, and the Record for how it's all gone." />

      <section className="hiw-step">
        <div className="hiw-step__num" aria-hidden="true">1</div>
        <div className="prose">
          <h2>The board: one card per game</h2>
          <p>
            Each card is a box score from the future. The big numbers beside each team are the sim's
            projected points; underneath, a bar shows how often each side wins across 10,000 runs.
          </p>
          <p>
            The <b>Spread</b>, <b>Total</b> and <b>ML</b> columns show the market's number, and the cents
            under it are the gap between the sim and the market price. Green means the sim likes that side
            more than the market does; red means less. A gap is not a bet on its own: the{" "}
            <Link to="/cfb/record">Record</Link> is where you see which gaps have actually paid.
          </p>
          <p>During games the card goes live: score, clock, field position and a win-probability strip.</p>
        </div>
        <Shot src="/about/board-card.png" w={736} h={346}
          alt="A game card from the scoreboard: two teams, projected points, spread, total and moneyline cells with cents edges, and a win-probability bar"
          caption="A card on the board. Projected points, the market lines, and the sim's edge in cents." />
      </section>

      <section className="hiw-step">
        <div className="hiw-step__num" aria-hidden="true">2</div>
        <div className="prose">
          <h2>Game sims: the whole range, not one number</h2>
          <p>
            Pick a game and you get every simulated outcome as a histogram: the margin, the total, each team's
            points, and any player's stat line. Type a line into the box (say, your book's spread) and it tells
            you how often the sim lands under, on, and over it.
          </p>
          <p>
            A tall, narrow peak near the line means half a point matters a lot. A wide, flat spread means the
            game is a coin flip with extra steps.
          </p>
        </div>
        <Shot src="/about/game-sims.png" w={1520} h={774}
          alt="Game sims page: a histogram of simulated score margins with a dashed line at the entered spread and the under and over percentages beneath"
          caption="Game sims. Set a line and read the under / over split straight off 10,000 runs." />
      </section>

      <section className="hiw-step">
        <div className="hiw-step__num" aria-hidden="true">3</div>
        <div className="prose">
          <h2>The Record: did any of it work?</h2>
          <p>
            Every starred pick, graded at the price when it was posted, fees in. The headline is the return on
            every unit risked; underneath are the running total, whether the market moved our way after we
            posted, and a chart of whether we hit as often as we said we would.
          </p>
          <p>
            Filters let you slice it any way you like: by market, week, team, conference or price. The default
            view is the starred picks, one per market, with long shots under 10¢ and heavy favorites over 90¢
            left out.
          </p>
        </div>
        <Shot src="/about/record.png" w={1520} h={1107}
          alt="The Record page: the season's return per unit, the win-loss record, and the running units line through the season"
          caption="The Record. The bad weeks are in there too." />
      </section>

      <div className="hiw-cta">
        <ButtonLink to="/cfb/scoreboard">Open this week's board</ButtonLink>
        <ButtonLink to="/about" variant="quiet">About MVPEAV</ButtonLink>
      </div>
    </div>
  );
}
